from collections import deque,defaultdict
h,w=A4.shape
lab=np.full((h,w),-1,int); cellsall=[]
for r in range(h):
 for c in range(w):
  if A4[r,c]==6 or lab[r,c]>=0: continue
  i=len(cellsall); q=deque([(r,c)]);lab[r,c]=i; cells=[]
  while q:
   p=q.popleft(); cells.append(p)
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    rr,cc=p[0]+dr,p[1]+dc
    if 0<=rr<h and 0<=cc<w and A4[rr,cc]!=6 and lab[rr,cc]<0:
     lab[rr,cc]=i;q.append((rr,cc))
  cellsall.append(cells)
pred=A4.copy(); comp_info=[]
for i,cells in enumerate(cellsall):
 dist={};q=deque()
 for r,c in cells:
  if any(not(0<=r+dr<h and 0<=c+dc<w) or A4[r+dr,c+dc]==6 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
   dist[(r,c)]=0;q.append((r,c))
 while q:
  p=q.popleft();r,c=p
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   pp=(r+dr,c+dc)
   if pp in cells and pp not in dist:
    dist[pp]=dist[p]+1;q.append(pp)
 md=defaultdict(set)
 for r,c in cells:
  if A4[r,c] not in (3,6): md[dist[(r,c)]].add(int(A4[r,c]))
 seq={d:sorted(v) for d,v in md.items()}
 print('comp',i,'size',len(cells),'bbox', (min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells)),'maxd',max(dist.values()),'marker depths',dict(seq))
 # use markers for consecutive depths if present; if no marker use bg=3 perhaps
 if md:
  maxmarker=max(md)
  # fill by cycling sorted colors layer order for consecutive depths from 0, fallback if not present
  s=[]
  for d in range(maxmarker+1):
   if d in md and len(md[d])==1:s.append(next(iter(md[d])))
   else: s.append(3)
  for p,dd in dist.items(): pred[p]=s[dd%len(s)]
print('mismatches',np.count_nonzero(pred!=O4))
# mismatch coords summary
mis=np.argwhere(pred!=O4)
print([(tuple(p),int(A4[tuple(p)]),int(pred[tuple(p)]),int(O4[tuple(p)]),int(lab[tuple(p)])) for p in mis[:100]])

